* Terminal Box Drawing */\n  .terminal-box {\n    @apply border border-crt-amber/60;\n    box-shadow:\n      0 0 10px rgba(255, 176, 0, 0.2),\n      inset 0 0 30px rgba(255, 176, 0, 0.03);\n  }\n\n  /* Glitch Effect Layers */\n  .glitch-container {\n    @apply relative;\n  }\n\n  .glitch-img {\n    @apply absolute inset-0 bg-cover bg-center;\n    filter: grayscale(100%) sepia(100%) hue-rotate(0deg) saturate(500%) contrast(1.2);\n  }\n\n  .glitch-img::before,\n  .glitch-img::after {\n    content: '';\n    @apply absolute inset-0 bg-cover bg-center;\n    background-image: inherit;\n  }\n\n  .glitch-img::before {\n    animation: glitch-anim-1 2s infinite linear alternate-reverse;\n    clip-path: polygon(0 0, 100% 0, 100% 35%, 0 35%);\n    filter: grayscale(100%) sepia(100%) hue-rotate(-10deg);\n  }\n\n  .glitch-img::after {\n    animation: glitch-anim-2 3s infinite linear alternate-reverse;\n    clip-path: polygon(0 65%, 100% 65%, 100% 100%, 0 100%);\n    filter: grayscale(100%) sepia(100%) hue-rotate(10deg);\n  }\n\n  /* Blinking Cursor */\n  .cursor-blink::after {\n    content: '█';\n    @apply animate-cursor-blink text-crt-amber;\n  }\n\n  /* Noise overlay */\n  .crt-noise {\n    @apply pointer-events-none fixed inset-0 z-30 opacity-5;\n    background-image: url(\"data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E\");\n  }\n\n  /* Moving scanline bar */\n  .crt-scanline-bar {\n    @apply pointer-events-none fixed left-0 right-0 h-1 z-40 opacity-10;\n    background: linear-gradient(\n      to bottom,\n      transparent,\n      rgba(255, 176, 0, 0.3),\n      transparent\n    );\n    animation: scanline-move 4s linear infinite;\n  }\n}\n\n@layer utilities {\n  /* Phosphor glow on focus/hover */\n  .phosphor-glow {\n    text-shadow:\n      0 0 5px #ffb000,\n      0 0 10px #ffb000,\n      0 0 20px #ff9500,\n      0 0 40px #ff9500;\n  }\n}\n\n/* Glitch Animations */\n@keyframes glitch-anim-1 {\n  0%, 100% {\n    transform: translate(0);\n    opacity: 1;\n  }\n  20% {\n    transform: translate(-3px, 1px);\n    opacity: 0.8;\n  }\n  40% {\n    transform: translate(3px, -1px);\n    opacity: 0.9;\n  }\n  60% {\n    transform: translate(-2px, 2px);\n    opacity: 0.7;\n  }\n  80% {\n    transform: translate(2px, -2px);\n    opacity: 0.85;\n  }\n}\n\n@keyframes glitch-anim-2 {\n  0%, 100% {\n    transform: translate(0);\n    opacity: 0.9;\n  }\n  25% {\n    transform: translate(4px, 1px);\n    opacity: 0.7;\n  }\n  50% {\n    transform: translate(-3px, -2px);\n    opacity: 0.8;\n  }\n  75% {\n    transform: translate(2px, 3px);\n    opacity: 0.6;\n  }\n}\n\n@keyframes scanline-move {\n  0% {\n    top: -10px;\n  }\n  100% {\n    top: 100vh;\n  }\n}\n\n/* Chromatic aberration for intense glitch moments */\n@keyframes chromatic-shift {\n  0%, 100% {\n    text-shadow:\n      -1px 0 #ff0000,\n      1px 0 #00ffff,\n      0 0 5px #ffb000;\n  }\n  25% {\n    text-shadow:\n      -2px 0 #ff0000,\n      2px 0 #00ffff,\n      0 0 8px #ffb000;\n  }\n  50% {\n    text-shadow:\n      1px 0 #ff0000,\n      -1px 0 #00ffff,\n      0 0 5px #ffb000;\n  }\n  75% {\n    text-shadow:\n      2px 0 #ff0000,\n      -2px 0 #00ffff,\n      0 0 10px #ffb000;\n  }\n}\n"],"sourceRoot":""}]);
